// qsm-toolbox's function-hooks module.
import type { On } from "claude-code";
import { registerNoun } from "./noun.generated.ts";

export function register(on: On): void {
  // Adds $.toolbox: one method per qsm-toolbox verb, generated by lib/generate-noun.ts. Never
  // hand-edit noun.generated.ts or types/index.d.ts.
  registerNoun(on);
}

